import java.util.*;

public class Main {
    static final long INF = (long)1e18;
    static long total_moves = 0;
    static long[] cache;

    static int calculate_steps(long n) {
        if (n == 0) return 0;
        if (n < cache.length && cache[(int)n] != 0) return (int)cache[(int)n];

        long min_diff = INF;
        long x = 1;
        int steps = 0;

        while (Math.abs(x - n) <= min_diff) {
            min_diff = Math.abs(x - n);
            x = x * 10 + 1;
            steps++;
        }
        x /= 10;

        if (x > n && x / 10 != 0) {
            if (n < cache.length) {
                return (int) Math.min(
                    steps + calculate_steps(Math.abs(x - n)),
                    steps - 1 + calculate_steps(Math.abs(x / 10 - n))
                );
            }
            return (int) Math.min(
                steps + calculate_steps(Math.abs(x - n)),
                steps - 1 + calculate_steps(Math.abs(x / 10 - n))
            );
        }
        if (n < cache.length) {
            return (int) (steps + calculate_steps(Math.abs(x - n)));
        }
        return (int) (steps + calculate_steps(Math.abs(x - n)));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        cache = new long[10000000];
        System.out.println(calculate_steps(n));
        sc.close();
    }
}
